UPDATE public.contextos SET contenido='<p>La gráfica muestra el porcentaje de ventas del último año de una empresa de álbumes musicales en tres idiomas: inglés, francés y español.</p><figure class="ctx-fig"><img src="img/figuras/mat/al1-q02-albumes.webp" loading="lazy" alt="Gráfica de barras de porcentaje de ventas por idioma: inglés alrededor del 35 %, español alrededor del 40 %, francés alrededor del 30 %. La barra del francés es la más baja."></figure><p>Al ver la gráfica, un ejecutivo de la empresa interpreta que la menor parte de los álbumes musicales vendidos en el último año fueron los del idioma francés.</p>' WHERE id='de904c14-000f-4eee-8745-515032d826ab' AND contenido='<p>La gráfica muestra el porcentaje de ventas del último año de una empresa de álbumes musicales en tres idiomas: inglés, francés y español.</p><figure class="ctx-fig"><img src="img/figuras/mat/al1-q02-albumes.webp" loading="lazy" alt="Gráfica de barras de porcentaje de ventas por idioma: inglés alrededor del 35 %, español alrededor del 38 %, francés alrededor del 28 %. La barra del francés es la más baja."></figure><p>Al ver la gráfica, un ejecutivo de la empresa interpreta que la menor parte de los álbumes musicales vendidos en el último año fueron los del idioma francés.</p>';
