UPDATE public.contextos SET contenido='<p>En una universidad se determinó que los futuros códigos de los estudiantes admitidos a primer semestre estarán compuestos por 6 casillas. En las 2 primeras casillas del código se deben ubicar los últimos 2 números del año de ingreso, y en cada una de las 4 casillas restantes es posible ubicar cualquier número de 0 a 9 con opción de repetirlos, así:</p><p>Si ingresara en el año 2050:</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><td>5</td><td>0</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td colspan="2">Últimos dígitos del año</td><td colspan="4">Cualquier dígito de 0 a 9</td></tr></table></div>' WHERE id='8c91a636-a3f1-40df-b1ca-0998bf42ba72' AND contenido='<p>En una universidad se determinó que los futuros códigos de los estudiantes admitidos a primer semestre estarán compuestos por 6 casillas. En las 2 primeras casillas del código se deben ubicar los últimos 2 números del año de ingreso, y en cada una de las 4 casillas restantes es posible ubicar cualquier número de 0 a 9 con opción de repetirlos, así:</p><p>Si ingresara en el año 2050:</p><table class="ctx-table"><tr><td>5</td><td>0</td><td>—</td><td>—</td><td>—</td><td>—</td></tr><tr><td colspan="2">Últimos dígitos del año</td><td colspan="4">Cualquier dígito de 0 a 9</td></tr></table>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 8c91a636-a3f1-40df-b1ca-0998bf42ba72'; END IF;
