UPDATE public.contextos SET contenido='<p>Una empresa productora de tres marcas de artículos para el hogar dona una parte de las utilidades de cada marca a las reservas naturales de la región.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Marca</th><th>1</th><th>2</th><th>3</th></tr><tr><td>Costo producción mensual (millones)</td><td>70</td><td>40</td><td>60</td></tr><tr><td>Ventas mensuales (millones)</td><td>100</td><td>60</td><td>—</td></tr><tr><td>Utilidad anual (millones)</td><td>360</td><td>240</td><td>300</td></tr><tr><td>Donación (millones)</td><td>54</td><td>36</td><td>—</td></tr></table></div><p>Para conocer el valor que cada una de las marcas dona a las reservas, se efectúa el siguiente procedimiento:</p><ol><li>Se realiza la resta entre las ventas y el costo de producción.</li><li>Se multiplica por 12 el valor obtenido en el paso 1.</li><li>Se multiplica por 15 el valor del paso 2, y luego se divide entre 100.</li></ol><p>La persona encargada de las donaciones necesita saber cuánto debe donar la marca número 3, pero ha perdido la información correspondiente a las ventas mensuales de esta marca.</p>' WHERE id='86edc719-0033-4397-b789-0a174e84a134' AND contenido='<p>Una empresa productora de tres marcas de artículos para el hogar dona una parte de las utilidades de cada marca a las reservas naturales de la región.</p><table class="ctx-table"><tr><th>Marca</th><th>1</th><th>2</th><th>3</th></tr><tr><td>Costo producción mensual (millones)</td><td>70</td><td>40</td><td>60</td></tr><tr><td>Ventas mensuales (millones)</td><td>100</td><td>60</td><td>—</td></tr><tr><td>Utilidad anual (millones)</td><td>360</td><td>240</td><td>300</td></tr><tr><td>Donación (millones)</td><td>54</td><td>36</td><td>—</td></tr></table><p>Para conocer el valor que cada una de las marcas dona a las reservas, se efectúa el siguiente procedimiento:</p><ol><li>Se realiza la resta entre las ventas y el costo de producción.</li><li>Se multiplica por 12 el valor obtenido en el paso 1.</li><li>Se multiplica por 15 el valor del paso 2, y luego se divide entre 100.</li></ol><p>La persona encargada de las donaciones necesita saber cuánto debe donar la marca número 3, pero ha perdido la información correspondiente a las ventas mensuales de esta marca.</p>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 86edc719-0033-4397-b789-0a174e84a134'; END IF;
UPDATE public.contextos SET contenido='<p>En la tabla se registran los materiales necesarios para la construcción de un muro; y en la gráfica, el costo total acumulado de los materiales.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Material</th><th>Unidades</th><th>Costo unidad ($)</th><th>Costo total ($)</th></tr><tr><td>Ladrillos</td><td>50</td><td>1</td><td>50</td></tr><tr><td>Varillas</td><td>10</td><td>5</td><td>50</td></tr><tr><td>Bulto de arena</td><td>5</td><td>5</td><td>25</td></tr><tr><td>Bulto de cemento</td><td>5</td><td>10</td><td>50</td></tr></table></div><figure class="ctx-fig"><svg viewBox="0 0 480 290" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Gráfica de barras del costo acumulado: ladrillos 50 pesos; ladrillos y varillas 100; ladrillos, varillas y bulto de arena 150; y costo total 200." font-family="var(--font-body), system-ui, sans-serif"><path d="M58 242H466M58 213.5H466M58 185H466M58 156.5H466M58 128H466M58 99.5H466M58 71H466M58 42.5H466M58 14H466" stroke="var(--color-line)" fill="none" stroke-dasharray="3 3"/><path d="M58 242H466" stroke="var(--color-line)" fill="none"/><g font-size="12" fill="var(--color-ink-faint)" text-anchor="end"><text x="51" y="246">0</text><text x="51" y="217.5">25</text><text x="51" y="189">50</text><text x="51" y="160.5">75</text><text x="51" y="132">100</text><text x="51" y="103.5">125</text><text x="51" y="75">150</text><text x="51" y="46.5">175</text><text x="51" y="18">200</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text transform="translate(13,128) rotate(-90)">Costo acumulado ($)</text></g><g fill="var(--color-accent-lite)"><rect x="85" y="185" width="48" height="57" rx="2"/><rect x="187" y="128" width="48" height="114" rx="2"/><rect x="289" y="71" width="48" height="171" rx="2"/><rect x="391" y="14" width="48" height="228" rx="2"/></g><g font-size="12" font-weight="600" fill="var(--color-ink)" text-anchor="middle"><text x="109" y="179">50</text><text x="211" y="122">100</text><text x="313" y="65">150</text><text x="415" y="8">200</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="end"><text x="109" y="258" transform="rotate(-30 109 258)">Ladrillos</text><text x="211" y="258" transform="rotate(-30 211 258)">+ varillas</text><text x="313" y="258" transform="rotate(-30 313 258)">+ arena</text><text x="415" y="258" transform="rotate(-30 415 258)">Costo total</text></g></svg></figure><p>Un analista de construcción afirma que la gráfica es inconsistente con los datos presentados en la tabla.</p>' WHERE id='bacfe984-ba24-4e26-9ebe-286f49adc3ba' AND contenido='<p>En la tabla se registran los materiales necesarios para la construcción de un muro; y en la gráfica, el costo total acumulado de los materiales.</p><table class="ctx-table"><tr><th>Material</th><th>Unidades</th><th>Costo unidad ($)</th><th>Costo total ($)</th></tr><tr><td>Ladrillos</td><td>50</td><td>1</td><td>50</td></tr><tr><td>Varillas</td><td>10</td><td>5</td><td>50</td></tr><tr><td>Bulto de arena</td><td>5</td><td>5</td><td>25</td></tr><tr><td>Bulto de cemento</td><td>5</td><td>10</td><td>50</td></tr></table><figure class="ctx-fig"><svg viewBox="0 0 480 290" width="100%" preserveAspectRatio="xMidYMid meet" role="img" aria-label="Gráfica de barras del costo acumulado: ladrillos 50 pesos; ladrillos y varillas 100; ladrillos, varillas y bulto de arena 150; y costo total 200." font-family="var(--font-body), system-ui, sans-serif"><path d="M58 242H466M58 213.5H466M58 185H466M58 156.5H466M58 128H466M58 99.5H466M58 71H466M58 42.5H466M58 14H466" stroke="var(--color-line)" fill="none" stroke-dasharray="3 3"/><path d="M58 242H466" stroke="var(--color-line)" fill="none"/><g font-size="12" fill="var(--color-ink-faint)" text-anchor="end"><text x="51" y="246">0</text><text x="51" y="217.5">25</text><text x="51" y="189">50</text><text x="51" y="160.5">75</text><text x="51" y="132">100</text><text x="51" y="103.5">125</text><text x="51" y="75">150</text><text x="51" y="46.5">175</text><text x="51" y="18">200</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="middle"><text transform="translate(13,128) rotate(-90)">Costo acumulado ($)</text></g><g fill="var(--color-accent-lite)"><rect x="85" y="185" width="48" height="57" rx="2"/><rect x="187" y="128" width="48" height="114" rx="2"/><rect x="289" y="71" width="48" height="171" rx="2"/><rect x="391" y="14" width="48" height="228" rx="2"/></g><g font-size="12" font-weight="600" fill="var(--color-ink)" text-anchor="middle"><text x="109" y="179">50</text><text x="211" y="122">100</text><text x="313" y="65">150</text><text x="415" y="8">200</text></g><g font-size="12" fill="var(--color-ink-soft)" text-anchor="end"><text x="109" y="258" transform="rotate(-30 109 258)">Ladrillos</text><text x="211" y="258" transform="rotate(-30 211 258)">+ varillas</text><text x="313" y="258" transform="rotate(-30 313 258)">+ arena</text><text x="415" y="258" transform="rotate(-30 415 258)">Costo total</text></g></svg></figure><p>Un analista de construcción afirma que la gráfica es inconsistente con los datos presentados en la tabla.</p>';
