UPDATE public.contextos SET contenido='<p>En un colegio se ofrecen seis deportes, para los estudiantes que practiquen durante el año. Un estudiante elaboró una tabla que relaciona la cantidad de deportes que puede elegir y la cantidad de posibilidades distintas que hay para seleccionarlos.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Cantidad de deportes escogidos</th><th>Número de posibilidades</th></tr><tr><td>2</td><td>6! ÷ (2! · (6 − 2)!) = 15</td></tr><tr><td>3</td><td>6! ÷ (3! · (6 − 3)!) = 20</td></tr></table></div><p>De un conjunto con n elementos, se deben seleccionar r elementos.</p><p><b>Combinaciones:</b> cuando no importa el orden en el que se selecciona cada deporte, C(n, r) = n! ÷ (r! · (n − r)!).<br><b>Permutaciones:</b> cuando sí importa el orden en que se selecciona cada deporte, P(n, r) = n! ÷ (n − r)!.</p>' WHERE id='14b23675-33fb-44c1-90e5-d72b208a0ca0' AND contenido='<p>En un colegio se ofrecen seis deportes, para los estudiantes que practiquen durante el año. Un estudiante elaboró una tabla que relaciona la cantidad de deportes que puede elegir y la cantidad de posibilidades distintas que hay para seleccionarlos.</p><table class="ctx-table"><tr><th>Cantidad de deportes escogidos</th><th>Número de posibilidades</th></tr><tr><td>2</td><td>6! ÷ (2! · (6 − 2)!) = 15</td></tr><tr><td>3</td><td>6! ÷ (3! · (6 − 3)!) = 20</td></tr></table><p>De un conjunto con n elementos, se deben seleccionar r elementos.</p><p><b>Combinaciones:</b> cuando no importa el orden en el que se selecciona cada deporte, C(n, r) = n! ÷ (r! · (n − r)!).<br><b>Permutaciones:</b> cuando sí importa el orden en que se selecciona cada deporte, P(n, r) = n! ÷ (n − r)!.</p>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 14b23675-33fb-44c1-90e5-d72b208a0ca0'; END IF;
UPDATE public.contextos SET contenido='<p>En un parque hay cuatro puntos (P, Q, R y S), los cuales están conectados por caminos rectos y curvos. La siguiente tabla muestra la distancia que hay entre varios pares de puntos, bien sea por los caminos rectos o por los curvos.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Punto inicial</th><th>Punto final</th><th>Camino recto</th><th>Camino curvo</th></tr><tr><td>P</td><td>Q</td><td>3 m</td><td>3,5 m</td></tr><tr><td>P</td><td>R</td><td>4 m</td><td>4,5 m</td></tr><tr><td>Q</td><td>S</td><td>4 m</td><td>4,5 m</td></tr><tr><td>Q</td><td>R</td><td>5 m</td><td>No hay camino</td></tr><tr><td>S</td><td>R</td><td>3 m</td><td>3,5 m</td></tr></table></div><p>Un estudiante quiere desplazarse desde el punto Q hasta el R, recorriendo la menor distancia. Él sugiere la siguiente ruta: desde el punto Q al S y luego del S al R, por los caminos rectos.</p>' WHERE id='eb672654-4670-42e2-a3e4-d00d8366bf50' AND contenido='<p>En un parque hay cuatro puntos (P, Q, R y S), los cuales están conectados por caminos rectos y curvos. La siguiente tabla muestra la distancia que hay entre varios pares de puntos, bien sea por los caminos rectos o por los curvos.</p><table class="ctx-table"><tr><th>Punto inicial</th><th>Punto final</th><th>Camino recto</th><th>Camino curvo</th></tr><tr><td>P</td><td>Q</td><td>3 m</td><td>3,5 m</td></tr><tr><td>P</td><td>R</td><td>4 m</td><td>4,5 m</td></tr><tr><td>Q</td><td>S</td><td>4 m</td><td>4,5 m</td></tr><tr><td>Q</td><td>R</td><td>5 m</td><td>No hay camino</td></tr><tr><td>S</td><td>R</td><td>3 m</td><td>3,5 m</td></tr></table><p>Un estudiante quiere desplazarse desde el punto Q hasta el R, recorriendo la menor distancia. Él sugiere la siguiente ruta: desde el punto Q al S y luego del S al R, por los caminos rectos.</p>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto eb672654-4670-42e2-a3e4-d00d8366bf50'; END IF;
UPDATE public.contextos SET contenido='<p>En un colegio, se realizó una encuesta a los estudiantes de un curso para conocer la cantidad de veces que les ha citado sus acudientes al colegio. Los resultados se muestran en la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><tr><th>Número de citaciones en el año</th><th>Cantidad de estudiantes</th></tr><tr><td>0</td><td>7</td></tr><tr><td>1</td><td>5</td></tr><tr><td>2</td><td>6</td></tr><tr><td>3</td><td>4</td></tr></table></div>' WHERE id='67260b31-6ec8-42fa-93c7-f4b9ae35d00b' AND contenido='<p>En un colegio, se realizó una encuesta a los estudiantes de un curso para conocer la cantidad de veces que les ha citado sus acudientes al colegio. Los resultados se muestran en la tabla.</p><table class="ctx-table"><tr><th>Número de citaciones en el año</th><th>Cantidad de estudiantes</th></tr><tr><td>0</td><td>7</td></tr><tr><td>1</td><td>5</td></tr><tr><td>2</td><td>6</td></tr><tr><td>3</td><td>4</td></tr></table>';
