UPDATE public.contextos SET contenido='<p>Cinco vacas se pesan por la mañana. Cada una consume cerca de 10 kg de comida durante el día y 10 litros de agua principalmente de noche. El productor escoge un camión liviano, pero al cargarlo por la tarde supera su capacidad.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Vaca</th><th scope="col">Peso en la mañana (kg)</th></tr></thead><tbody><tr><th scope="row">1</th><td>652</td></tr><tr><th scope="row">2</th><td>690</td></tr><tr><th scope="row">3</th><td>774</td></tr><tr><th scope="row">4</th><td>676</td></tr><tr><th scope="row">5</th><td>703</td></tr><tr><th scope="row">Total</th><td>3.495</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Tipo de camión</th><th scope="col">Capacidad máxima (kg)</th></tr></thead><tbody><tr><th scope="row">Ligero</th><td>2.500</td></tr><tr><th scope="row">Liviano</th><td>3.500</td></tr><tr><th scope="row">Mediano</th><td>4.500</td></tr><tr><th scope="row">Pesado</th><td>7.500</td></tr></tbody></table></div>' WHERE id='96afdd48-7b40-4e2f-a5fe-e40182564b5f' AND contenido='<p>Cinco vacas se pesan por la mañana. Cada una consume cerca de 10 kg de comida durante el día y 10 litros de agua principalmente de noche. El productor escoge un camión liviano, pero al cargarlo por la tarde supera su capacidad.</p><figure class="ctx-fig"><img src="img/figuras/mat/bu2-q46-tablas.webp" alt="Pesos 652, 690, 774, 676 y 703 kg: total 3.495. Capacidades de camiones: ligero 2.500, liviano 3.500, mediano 4.500 y pesado 7.500 kg." loading="lazy"></figure>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 96afdd48-7b40-4e2f-a5fe-e40182564b5f'; END IF;
