UPDATE public.contextos SET contenido='<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><div class="ctx-datos" role="region" aria-label="Porcentaje de personas por salario" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Porcentaje de personas por salario</caption><thead><tr><th scope="col">Salario</th><th scope="col">Hombres</th><th scope="col">Mujeres</th><th scope="col">Total</th></tr></thead><tbody><tr><th scope="row">$1.000.000</th><td>2 %</td><td>18 %</td><td>40</td></tr><tr><th scope="row">$1.500.000</th><td>15 %</td><td>10 %</td><td>50</td></tr><tr><th scope="row">$2.000.000</th><td>21 %</td><td>14 %</td><td>70</td></tr><tr><th scope="row">$3.000.000</th><td>12 %</td><td>8 %</td><td>40</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Porcentaje destinado a cuotas</th><th scope="col">$1.000.000</th><th scope="col">$1.500.000</th><th scope="col">$2.000.000</th><th scope="col">$3.000.000</th></tr></thead><tbody><tr><th scope="row">15 %</th><td>10</td><td>15</td><td>25</td><td>10</td></tr><tr><th scope="row">35 %</th><td>24</td><td>24</td><td>31</td><td>25</td></tr><tr><th scope="row">Total de personas por salario</th><td>34</td><td>39</td><td>56</td><td>35</td></tr></tbody></table></div>' WHERE id='43fdd7c5-32da-476a-baf6-ceb00e01ae70' AND contenido='<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q01-tablas.webp" alt="Salarios de 1, 1,5, 2 y 3 millones: 40, 50, 70 y 40 personas. Con salario de 2 millones hay 42 hombres y 28 mujeres; 25 personas pagan el 15 % y 31 pagan el 35 %." loading="lazy"></figure>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 43fdd7c5-32da-476a-baf6-ceb00e01ae70'; END IF;
UPDATE public.contextos SET contenido='<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><div class="ctx-datos" role="region" aria-label="Porcentaje de personas por salario" tabindex="0"><table class="ctx-table ctx-table-nativa"><caption>Porcentaje de personas por salario</caption><thead><tr><th scope="col">Salario</th><th scope="col">Hombres</th><th scope="col">Mujeres</th><th scope="col">Total</th></tr></thead><tbody><tr><th scope="row">$1.000.000</th><td>2 %</td><td>18 %</td><td>40</td></tr><tr><th scope="row">$1.500.000</th><td>15 %</td><td>10 %</td><td>50</td></tr><tr><th scope="row">$2.000.000</th><td>21 %</td><td>14 %</td><td>70</td></tr><tr><th scope="row">$3.000.000</th><td>12 %</td><td>8 %</td><td>40</td></tr></tbody></table></div><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa ctx-table-amplia"><thead><tr><th scope="col">Porcentaje destinado a cuotas</th><th scope="col">$1.000.000</th><th scope="col">$1.500.000</th><th scope="col">$2.000.000</th><th scope="col">$3.000.000</th></tr></thead><tbody><tr><th scope="row">15 %</th><td>10</td><td>15</td><td>25</td><td>10</td></tr><tr><th scope="row">35 %</th><td>24</td><td>24</td><td>31</td><td>25</td></tr><tr><th scope="row">Total de personas por salario</th><td>34</td><td>39</td><td>56</td><td>35</td></tr></tbody></table></div><p>Un analista promedia los porcentajes: (15 % + 35 %)/2 = 25 %. Luego promedia los usuarios: (25 + 31)/2 = 28. Finalmente calcula $2.000.000×28×25 % = $14.000.000.</p>' WHERE id='361bfcda-bd86-4556-b3c5-1ad4675b8ec9' AND contenido='<p>Se estudiaron los salarios de 200 personas; 164 tenían deudas de tarjeta de crédito. La tabla 1 distribuye las 200 personas según salario y sexo. La tabla 2 indica cuántas personas destinan el 15 % o el 35 % del salario a cuotas mensuales.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q01-tablas.webp" alt="Salarios de 1, 1,5, 2 y 3 millones: 40, 50, 70 y 40 personas. Con salario de 2 millones hay 42 hombres y 28 mujeres; 25 personas pagan el 15 % y 31 pagan el 35 %." loading="lazy"></figure><p>Un analista promedia los porcentajes: (15 % + 35 %)/2 = 25 %. Luego promedia los usuarios: (25 + 31)/2 = 28. Finalmente calcula $2.000.000×28×25 % = $14.000.000.</p>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto 361bfcda-bd86-4556-b3c5-1ad4675b8ec9'; END IF;
UPDATE public.contextos SET contenido='<p>Para estudiar correlación entre dos conjuntos con igual número de datos se proponen diferencias respecto a sus promedios, productos de esas diferencias y desviaciones estándar. La tabla muestra cinco personas.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Nombre</th><th scope="col">Peso (kg)</th><th scope="col">Edad</th><th scope="col">Color de ojos</th></tr></thead><tbody><tr><th scope="row">Paola</th><td>60</td><td>30</td><td>Verde</td></tr><tr><th scope="row">Andrea</th><td>50</td><td>23</td><td>Azul</td></tr><tr><th scope="row">Gloria</th><td>55</td><td>50</td><td>Café</td></tr><tr><th scope="row">Luis</th><td>52</td><td>18</td><td>Azul</td></tr><tr><th scope="row">Mario</th><td>53</td><td>20</td><td>Café</td></tr></tbody></table></div>' WHERE id='7630ef7c-c111-4728-9f77-470371f392e0' AND contenido='<p>Para estudiar correlación entre dos conjuntos con igual número de datos se proponen diferencias respecto a sus promedios, productos de esas diferencias y desviaciones estándar. La tabla muestra cinco personas.</p><figure class="ctx-fig"><img src="img/figuras/mat/do1-q04-tabla.webp" alt="Paola: 60 kg, 30 años, ojos verdes; Andrea: 50 kg, 23 años, azules; Gloria: 55 kg, 50 años, café; Luis: 52 kg, 18 años, azules; Mario: 53 kg, 20 años, café." loading="lazy"></figure>';
