UPDATE public.contextos SET contenido='<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$60.000</td><td>1.200</td></tr></tbody></table></div><p>Para identificar la mayor inversión se propone: 1. Ordenar los productos por costo de fabricación unitario. 2. Multiplicar costo unitario por unidades de cada producto. 3. Comparar los resultados y escoger el mayor.</p>' WHERE id='a0c40ee0-e6df-40ee-938c-4abf35f7b775' AND contenido='<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q22-calzado.webp" alt="Botas: costo $30.000, precio $32.000, 500 unidades; zapatillas: $25.000, $30.000, 800; deportivos: $35.000, $35.000, 2.000; formales: $50.000, $60.000, 1.200." loading="lazy"></figure><p>Para identificar la mayor inversión se propone: 1. Ordenar los productos por costo de fabricación unitario. 2. Multiplicar costo unitario por unidades de cada producto. 3. Comparar los resultados y escoger el mayor.</p>';
GET DIAGNOSTICS afectados = ROW_COUNT;
IF afectados <> 1 THEN RAISE EXCEPTION 'No coincide la versión previa: contexto a0c40ee0-e6df-40ee-938c-4abf35f7b775'; END IF;
UPDATE public.contextos SET contenido='<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><div class="ctx-datos" role="region" aria-label="Tabla de datos" tabindex="0"><table class="ctx-table ctx-table-nativa"><thead><tr><th scope="col">Producto</th><th scope="col">Costo de fabricación</th><th scope="col">Precio de venta</th><th scope="col">Unidades vendidas</th></tr></thead><tbody><tr><th scope="row">Botas</th><td>$30.000</td><td>$32.000</td><td>500</td></tr><tr><th scope="row">Zapatillas</th><td>$25.000</td><td>$30.000</td><td>800</td></tr><tr><th scope="row">Zapatos deportivos</th><td>$35.000</td><td>$35.000</td><td>2.000</td></tr><tr><th scope="row">Zapatos formales</th><td>$50.000</td><td>$60.000</td><td>1.200</td></tr></tbody></table></div><p>La utilidad neta total es de $17.000.000. Para hallar la participación de un producto se calcula (precio − costo)×unidades, se divide entre la utilidad total y se multiplica por 100.</p>' WHERE id='91bbd0aa-184b-4989-9c3e-fa005afd8386' AND contenido='<p>Una empresa vendió en 2014 todas las unidades de calzado de la tabla.</p><figure class="ctx-fig"><img src="img/figuras/mat/mi-q22-calzado.webp" alt="Botas: costo $30.000, precio $32.000, 500 unidades; zapatillas: $25.000, $30.000, 800; deportivos: $35.000, $35.000, 2.000; formales: $50.000, $60.000, 1.200." loading="lazy"></figure><p>La utilidad neta total es de $17.000.000. Para hallar la participación de un producto se calcula (precio − costo)×unidades, se divide entre la utilidad total y se multiplica por 100.</p>';
